//! Per-version numeric tables. The `v<protocol>.rs` files are generated by `tools/re/gen_tables.py`
//! from the reports of the official server (numbers and registry names only).

mod v765;
mod v767;
mod v769;
mod v777;

/// Declares the packet-id struct; the field list matches `FIELDS` in `tools/re/gen_tables.py`.
macro_rules! packets {
    ($($field:ident),+ $(,)?) => {
        /// Packet ids of the packets this bot knows (`sb` = to the server, `cb` = to the client).
        /// -1: the release has no such packet.
        #[derive(Debug)]
        pub struct Packets { $(pub $field: i32),+ }
    };
}

packets!(
    sb_handshake_intention, sb_status_status_request, cb_status_status_response,
    sb_login_hello, sb_login_login_acknowledged,
    cb_login_login_disconnect, cb_login_hello, cb_login_login_finished, cb_login_login_compression,
    sb_config_client_information, sb_config_finish_configuration, sb_config_keep_alive, sb_config_pong,
    sb_config_select_known_packs,
    cb_config_disconnect, cb_config_finish_configuration, cb_config_keep_alive, cb_config_ping,
    cb_config_select_known_packs,
    sb_play_accept_teleportation, sb_play_chunk_batch_received, sb_play_client_tick_end, sb_play_keep_alive,
    sb_play_move_player_pos, sb_play_move_player_pos_rot, sb_play_pong, sb_play_player_action,
    sb_play_player_loaded, sb_play_set_carried_item, sb_play_set_creative_mode_slot, sb_play_swing,
    sb_play_use_item_on, sb_play_player_command, sb_play_player_input,
    cb_play_block_changed_ack, cb_play_block_update, cb_play_chunk_batch_finished, cb_play_disconnect, cb_play_forget_level_chunk, cb_play_game_event, cb_play_keep_alive,
    cb_play_level_chunk_with_light, cb_play_login, cb_play_ping, cb_play_player_position,
    cb_play_section_blocks_update, cb_play_set_health,
);

#[derive(Debug)]
pub struct Tables {
    pub protocol: i32,
    pub state_count: u32,
    pub packets: Packets,
    /// Item names; the index is the item registry id.
    pub items: &'static [&'static str],
    /// (block, first state id, default state id, number of states), sorted by first id.
    pub blocks: &'static [(&'static str, u32, u32, u32)],
}

impl Tables {
    pub fn item_id(&self, name: &str) -> Option<i32> {
        let key = name.strip_prefix("minecraft:").unwrap_or(name);
        self.items.iter().position(|&n| n == key).map(|i| i as i32)
    }

    /// The block that owns a block state id.
    pub fn block_of_state(&self, state: u32) -> Option<&'static str> {
        let i = self.blocks.partition_point(|b| b.1 <= state);
        let (name, first, _, count) = *self.blocks.get(i.checked_sub(1)?)?;
        (state < first + count).then_some(name)
    }

    /// Default state id of a block.
    pub fn default_state(&self, name: &str) -> Option<u32> {
        let key = name.strip_prefix("minecraft:").unwrap_or(name);
        self.blocks.iter().find(|b| b.0 == key).map(|b| b.2)
    }
}

pub static V765: &Tables = &v765::TABLES;
pub static V767: &Tables = &v767::TABLES;
pub static V769: &Tables = &v769::TABLES;
pub static V777: &Tables = &v777::TABLES;
